exercises.solution:
**`prevent_destroy`**:

```hcl
resource "azurerm_postgresql_flexible_server" "records" {    # any resource type works the same way
  # ...
  lifecycle {
    prevent_destroy = true
  }
}
```

With it set, any plan that would delete or replace the resource fails with an error, so a rename or a force-new attribute change cannot destroy it by accident. It only protects against plans from this configuration: removing the resource block from the code removes the protection with it, and the cloud console bypasses it entirely. That is why teams also turn on the provider's own protection for databases (a deletion-protection setting or a resource lock, which every major cloud offers), so that two independent switches must be flipped before data can be lost.

exercises.starter:
def plan(desired, state, force_new):
    """Compare the desired configuration with the recorded state.

    desired, state: {address: {attribute: value, ...}}; every resource has a "type" attribute.
    force_new:      {type: set of attribute names that cannot change in place}
    Return a list of (action, address) with action in "create", "update", "replace", "delete":
    first the desired addresses in sorted order (skipping unchanged ones), then the deletions
    in sorted order.
    """
    actions = []
    for addr in sorted(desired):
        if addr not in state:
            actions.append(("create", addr))
    return actions

exercises.tests:
FORCE = {"bucket": {"name", "region"}, "database": {"engine"}, "dns": set()}
state = {
    "bucket.logs":   {"type": "bucket", "name": "logs-7f", "region": "ap-south-1", "versioning": False},
    "bucket.media":  {"type": "bucket", "name": "media-7f", "region": "ap-south-1"},
    "database.main": {"type": "database", "engine": "postgres-16", "size": "small"},
    "dns.www":       {"type": "dns", "target": "203.0.113.10"},
}
desired = {
    "bucket.logs":   {"type": "bucket", "name": "logs-7f", "region": "ap-south-1", "versioning": True},
    "bucket.media":  {"type": "bucket", "name": "media-7f", "region": "eu-west-1"},
    "database.main": {"type": "database", "engine": "postgres-16", "size": "small"},
    "queue.jobs":    {"type": "queue", "retention_hours": 24},
}
assert plan(desired, state, FORCE) == [
    ("update", "bucket.logs"), ("replace", "bucket.media"), ("create", "queue.jobs"), ("delete", "dns.www"),
], plan(desired, state, FORCE)
assert plan(state, state, FORCE) == [], "an unchanged configuration plans nothing"
assert plan({}, state, FORCE) == [("delete", a) for a in sorted(state)]
added = {"database.main": {"type": "database", "engine": "postgres-16", "size": "small", "backup": "daily"}}
assert plan(added, {"database.main": state["database.main"]}, FORCE) == [("update", "database.main")], \
    "an attribute that appears for the first time is a change too"
removed = {"bucket.logs": {"type": "bucket", "name": "logs-7f", "region": "ap-south-1"}}
assert plan(removed, {"bucket.logs": state["bucket.logs"]}, FORCE) == [("update", "bucket.logs")], \
    "so is an attribute that disappears"
engine = {"database.main": {"type": "database", "engine": "postgres-17", "size": "large"}}
assert plan(engine, {"database.main": state["database.main"]}, FORCE) == [("replace", "database.main")], \
    "one force-new attribute among the changes is enough to force a replacement"

exercises.reference:
def plan(desired, state, force_new):
    actions = []
    for addr in sorted(desired):
        want = desired[addr]
        if addr not in state:
            actions.append(("create", addr))
            continue
        have = state[addr]
        changed = {k for k in set(want) | set(have) if want.get(k) != have.get(k)}
        if not changed:
            continue
        if changed & force_new.get(want["type"], set()):
            actions.append(("replace", addr))
        else:
            actions.append(("update", addr))
    for addr in sorted(state):
        if addr not in desired:
            actions.append(("delete", addr))
    return actions

